-- Traffic Routing Optimizer — PostgreSQL schema (MODULE 3)
-- Apply with:  psql "$DATABASE_URL" -f backend/db/schema.sql   (or `npm run db:init`)
-- Idempotent: safe to run repeatedly.

CREATE TABLE IF NOT EXISTS users (
  id            SERIAL PRIMARY KEY,
  username      VARCHAR(64) UNIQUE NOT NULL,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- A road network. Built-in samples are generated by the DSA module and are not
-- stored here; this table holds user-created / saved networks.
CREATE TABLE IF NOT EXISTS graphs (
  id            SERIAL PRIMARY KEY,
  user_id       INTEGER REFERENCES users(id) ON DELETE SET NULL,
  name          VARCHAR(120) NOT NULL,
  description   TEXT NOT NULL DEFAULT '',
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Intersections / locations (x, y are canvas coordinates).
CREATE TABLE IF NOT EXISTS nodes (
  graph_id      INTEGER NOT NULL REFERENCES graphs(id) ON DELETE CASCADE,
  node_id       VARCHAR(64) NOT NULL,
  label         VARCHAR(120) NOT NULL,
  x             DOUBLE PRECISION NOT NULL,
  y             DOUBLE PRECISION NOT NULL,
  PRIMARY KEY (graph_id, node_id)
);

-- Roads. A bidirectional road is ONE row; the in-memory graph expands it into
-- two directed edges.
CREATE TABLE IF NOT EXISTS roads (
  graph_id         INTEGER NOT NULL REFERENCES graphs(id) ON DELETE CASCADE,
  road_id          VARCHAR(64) NOT NULL,
  source           VARCHAR(64) NOT NULL,
  destination      VARCHAR(64) NOT NULL,
  distance         DOUBLE PRECISION NOT NULL CHECK (distance > 0),
  base_travel_time DOUBLE PRECISION NOT NULL CHECK (base_travel_time > 0),
  traffic_level    DOUBLE PRECISION NOT NULL DEFAULT 1.0 CHECK (traffic_level BETWEEN 1.0 AND 3.0),
  is_blocked       BOOLEAN NOT NULL DEFAULT FALSE,
  bidirectional    BOOLEAN NOT NULL DEFAULT TRUE,
  PRIMARY KEY (graph_id, road_id),
  FOREIGN KEY (graph_id, source)      REFERENCES nodes(graph_id, node_id) ON DELETE CASCADE,
  FOREIGN KEY (graph_id, destination) REFERENCES nodes(graph_id, node_id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_roads_graph ON roads(graph_id);

-- Past simulation runs and their statistics. graph_id is NULL for runs on a
-- built-in sample network (sample_key says which one).
CREATE TABLE IF NOT EXISTS simulation_runs (
  id               SERIAL PRIMARY KEY,
  graph_id         INTEGER REFERENCES graphs(id) ON DELETE CASCADE,
  sample_key       VARCHAR(64),
  algorithm        VARCHAR(16) NOT NULL CHECK (algorithm IN ('BFS', 'DFS', 'Dijkstra')),
  mode             VARCHAR(24) NOT NULL CHECK (mode IN ('distance', 'time', 'avoidTraffic')),
  source           VARCHAR(64) NOT NULL,
  target           VARCHAR(64) NOT NULL,
  found            BOOLEAN NOT NULL,
  path             JSONB NOT NULL DEFAULT '[]',
  total_distance   DOUBLE PRECISION,
  total_time       DOUBLE PRECISION,
  total_cost       DOUBLE PRECISION,
  nodes_explored   INTEGER NOT NULL,
  edges_checked    INTEGER NOT NULL,
  execution_ms     DOUBLE PRECISION NOT NULL,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_runs_graph ON simulation_runs(graph_id, created_at DESC);

-- History of traffic / blockage events applied while simulating.
CREATE TABLE IF NOT EXISTS traffic_events (
  id               SERIAL PRIMARY KEY,
  graph_id         INTEGER REFERENCES graphs(id) ON DELETE CASCADE,
  sample_key       VARCHAR(64),
  road_id          VARCHAR(64) NOT NULL,
  event_type       VARCHAR(16) NOT NULL CHECK (event_type IN ('block', 'unblock', 'traffic')),
  old_traffic      DOUBLE PRECISION,
  new_traffic      DOUBLE PRECISION,
  route_changed    BOOLEAN NOT NULL DEFAULT FALSE,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_events_graph ON traffic_events(graph_id, created_at DESC);

-- Routes a user chose to keep.
CREATE TABLE IF NOT EXISTS saved_routes (
  id               SERIAL PRIMARY KEY,
  user_id          INTEGER REFERENCES users(id) ON DELETE SET NULL,
  graph_id         INTEGER REFERENCES graphs(id) ON DELETE CASCADE,
  sample_key       VARCHAR(64),
  name             VARCHAR(120) NOT NULL,
  source           VARCHAR(64) NOT NULL,
  target           VARCHAR(64) NOT NULL,
  mode             VARCHAR(24) NOT NULL,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now()
);
